from itertools import combinations
import numpy as np

# Generate all possible edges in the complete graph K_9
edges = list(combinations(range(9), 2))

# Initialize the colors of the edges
colors = np.zeros(len(edges), dtype=int)

# Function to check if a clique is monochromatic
def is_monochromatic(clique, colors):
    color = colors[edges.index(clique)]
    for i in range(len(clique)):
        for j in range(i+1, len(clique)):
            edge = tuple(sorted((clique[i], clique[j])))
            if colors[edges.index(edge)] != color:
                return False
    return True

# Function to check if the coloring is valid
def is_valid_coloring(colors):
    # Check for monochromatic red cliques of size 4
    for clique in combinations(range(9), 4):
        if is_monochromatic(clique, colors):
            return False
    # Check for monochromatic blue cliques of size 3
    for clique in combinations(range(9), 3):
        if is_monochromatic(clique, 1-colors):
            return False
    return True

# Try all possible colorings
for coloring in range(2**len(edges)):
    binary_coloring = [int(x) for x in bin(coloring)[2:].zfill(len(edges))]
    if is_valid_coloring(binary_coloring):
        print(binary_coloring)
        break
else:
    print("UNSATISFIABLE")
